import{_ as t,a,o as n,ai as o}from"./chunks/framework.BbOtTPsL.js";const p=JSON.parse('{"title":"List Channels","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"rest","title":"List Channels","description":"Paginated list of every channel (storefront) configured in the store.","query":"curl -X GET \\"https://your-domain.com/api/admin/settings/channels?per_page=10\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 1,\\n      \\"code\\": \\"default\\",\\n      \\"name\\": \\"Default Channel\\",\\n      \\"hostname\\": \\"store.example.com\\",\\n      \\"rootCategoryId\\": 1,\\n      \\"defaultLocaleId\\": 1,\\n      \\"baseCurrencyId\\": 1\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 10,\\n    \\"lastPage\\": 1,\\n    \\"total\\": 1,\\n    \\"from\\": 1,\\n    \\"to\\": 1\\n  }\\n}\\n"},{"id":"filtered","title":"Filtered + Sorted","description":"Narrow by code, name and hostname, sorted by name ascending. Supplying multiple filters narrows the result (logical AND).","query":"curl -X GET \\"https://your-domain.com/api/admin/settings/channels?code=default&name=Store&hostname=example.com&sort=name&order=asc&per_page=10\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\"\\n","response":"{\\n  \\"data\\": [\\n    {\\n      \\"id\\": 1,\\n      \\"code\\": \\"default\\",\\n      \\"name\\": \\"Default Channel\\",\\n      \\"hostname\\": \\"store.example.com\\",\\n      \\"rootCategoryId\\": 1,\\n      \\"defaultLocaleId\\": 1,\\n      \\"baseCurrencyId\\": 1\\n    }\\n  ],\\n  \\"meta\\": {\\n    \\"currentPage\\": 1,\\n    \\"perPage\\": 10,\\n    \\"lastPage\\": 1,\\n    \\"total\\": 1,\\n    \\"from\\": 1,\\n    \\"to\\": 1\\n  }\\n}\\n"}]},"headers":[],"relativePath":"api/rest-api/admin/settings/channels/list.md","filePath":"api/rest-api/admin/settings/channels/list.md","lastUpdated":1782473079000}'),d={name:"api/rest-api/admin/settings/channels/list.md"};function r(s,e,i,c,l,h){return n(),a("div",null,e[0]||(e[0]=[o('<h1 id="list-channels" tabindex="-1">List Channels <a class="header-anchor" href="#list-channels" aria-label="Permalink to &quot;List Channels&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th></tr></thead><tbody><tr><td><code>/api/admin/settings/channels</code></td><td>GET</td></tr></tbody></table><p>Returns every channel (storefront) configured in the store in the <code>{ data, meta }</code> envelope. Use it to audit which storefronts a store runs, or look up a channel&#39;s <code>id</code> before a detail / update / delete call.</p><h2 id="pagination" tabindex="-1">Pagination <a class="header-anchor" href="#pagination" aria-label="Permalink to &quot;Pagination&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Description</th></tr></thead><tbody><tr><td><code>page</code></td><td>Page number, 1-based. Default <code>1</code>.</td></tr><tr><td><code>per_page</code></td><td>Items per page. Default <code>10</code>, max <code>50</code>.</td></tr></tbody></table><h2 id="filters" tabindex="-1">Filters <a class="header-anchor" href="#filters" aria-label="Permalink to &quot;Filters&quot;">​</a></h2><p>Query parameters that narrow the result. Supplying more than one <strong>narrows further</strong> — they combine with logical <strong>AND</strong>. They mirror the admin Channels datagrid filters.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Match</th><th>Example</th></tr></thead><tbody><tr><td><code>code</code></td><td>Partial (contains), on the channel code.</td><td><code>?code=default</code></td></tr><tr><td><code>name</code></td><td>Partial (contains), on the channel&#39;s translated name.</td><td><code>?name=Store</code></td></tr><tr><td><code>hostname</code></td><td>Partial (contains), on the channel hostname.</td><td><code>?hostname=example.com</code></td></tr></tbody></table><h2 id="sorting" tabindex="-1">Sorting <a class="header-anchor" href="#sorting" aria-label="Permalink to &quot;Sorting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Values</th></tr></thead><tbody><tr><td><code>sort</code></td><td><code>id</code> (default), <code>code</code>, <code>name</code></td></tr><tr><td><code>order</code></td><td><code>asc</code>, <code>desc</code> (default <code>desc</code>)</td></tr></tbody></table><p>Both the compound form <code>?sort=name-asc</code> and the split form <code>?sort=name&amp;order=asc</code> are accepted.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Listing rows are <strong>slim</strong>: the detail-only nested data — <code>locales</code>, <code>currencies</code>, <code>inventorySources</code>, and <code>translations</code> — is not included here. Fetch a single channel with the detail endpoint to get it populated.</li><li><code>code</code> and <code>hostname</code> match against the channel row; <code>name</code> matches against the channel&#39;s translation for the current locale.</li></ul><p>See the <a href="./">Channels overview</a> for field meanings and behaviour.</p>',14)]))}const u=t(d,[["render",r]]);export{p as __pageData,u as default};
